/* ---------- built-in pack: MGMT 660 International Business Quest (IHRM Ch 4–7) ----------
   Written from the Chapter 4–7 lecture slides (Dowling, Festing & Engle, IHRM 8e).
   Also uses the predicted Exam 2 study guide in the Study Quest folder.
   Weighted toward the kinds of items on the Exam 1 review: named frameworks, lists,
   types/approaches, and advantages vs. disadvantages. Correct answer first; the game shuffles. */
const IHRM_QS = [];
const IM = (c, d, q, a, e, tbl) => IHRM_QS.push({ kind: "mc", c: String(c), d, q, a, e, tbl });
const IT = (c, d, q, tf, e) => IHRM_QS.push({ kind: "tf", c: String(c), d, q, tf, e });

/* ===== Chapter 4 — Global Work ===== */
IM(4, 1, "The taxonomy of global work experiences sorts global work along which three dimensions?", ["Cognitive flexibility, physical mobility, and non-work disruptions", "Assignment length, family size, and host-country language needs", "Cultural distance, job status, and the compensation package", "Physical mobility, salary level, and headquarters' support"], "Ch 4 slide 2: global work differs in the cognitive flexibility it demands, how much physical moving it involves, and how much it disrupts life outside work.");
IM(4, 2, "A software tester flies from Ireland to a different EU country every few weeks for 1–3 month projects and never relocates her family. Which global worker is she?", ["Flexpatriate", "Corporate expatriate", "Inpatriate", "Global domestic"], "Flexpatriates take frequent short trips (usually 1–3 months), often to several countries, without family. (Table 4.2)");
IM(4, 2, "An engineer lives in Belgium and crosses the border to work in the Netherlands every weekday (or every week), returning home regularly. Which type of global worker is this?", ["International commuter", "Flexpatriate", "Self-initiated expatriate", "Short-term assignee"], "International commuters live in one country and work in another, commuting home regularly. (Ch 4 slides 3, 13)");
IM(4, 2, "A manager never leaves her home office in Chicago but spends her day dealing with suppliers and colleagues in Asia and Europe by video and email. What is she?", ["A global domestic", "A flexpatriate", "An international commuter", "A corporate expatriate"], "Global domestics do international work from home, with little or no travel. (Ch 4 slides 3, 13)");
IM(4, 2, "A nurse from the Philippines finds her own job in Dubai and moves there without any employer sending her. Which category fits?", ["Self-initiated expatriate", "Corporate (assigned) expatriate", "Inpatriate", "Flexpatriate"], "Self-initiated expatriates (SIEs) choose and organize their own move abroad, rather than being sent by an employer. (Ch 4 slide 12)");
IM(4, 1, "Which global worker is sent by the parent company on an assignment of 12 months or more, usually with family?", ["Corporate (long-term) expatriate", "Short-term assignee", "Flexpatriate", "International business traveler"], "Table 4.2: corporate expatriates go for 12+ months, to one country, usually with family.");
IM(4, 2, "When assigned expatriates are compared by assignment length, what is the typical duration of a SHORT-TERM assignment?", ["3–12 months", "1–3 months", "12 months or more", "1–2 weeks"], "Short-term assignees: 3–12 months, in one or very few countries, usually without family.");
IM(4, 2, "Comparing corporate (long-term) expatriates, short-term assignees, and flexpatriates, which type has the HIGHEST risk of assignment failure and is the most cost-intensive?", ["Corporate (long-term) expatriates", "Short-term assignees (3–12 months)", "Flexpatriates (frequent short trips)", "International business travelers"], "Long-term expatriation is cost-intensive and carries higher failure risk; flexpatriates have lower risk and no notable extra costs.");
IM(4, 2, "For which type of assigned expatriate is repatriation 'challenging due to long-term planning issues'?", ["Corporate (long-term) expatriates", "Short-term assignees (3–12 months)", "Flexpatriates (frequent short trips)", "International commuters (weekly)"], "For short-term assignees and flexpatriates, repatriation is 'not a problem.'");
IM(4, 2, "How often do flexpatriates usually receive pre-departure training?", ["Usually no", "Usually yes", "Sometimes", "Always, by law"], "Pre-departure training: corporate expatriates usually yes; short-term assignees sometimes; flexpatriates usually no.");
IM(4, 2, "What is the IHRM department's role for corporate (long-term) expatriates compared with flexpatriates?", ["Responsible for all aspects vs. less involvement", "Less involvement vs. responsible for all aspects", "Responsible for all aspects of both types", "Shared with the host unit for both types"], "The IHRM role is largest for long-term expatriates. Short-term assignees and flexpatriates get less involvement.");
IM(4, 3, "Comparing corporate expatriates, short-term assignees, and flexpatriates, which statement about host-country language skills is correct?", ["Long-term: at least basic skills often required; flexpatriates: not necessarily required", "Long-term: not necessarily required; flexpatriates: fluency usually required", "Long-term and flexpatriates: basic skills always required; short-term: not necessarily required", "Short-term: fluency required; long-term and flexpatriates: basic skills only"], "Corporate: at least basic skills are often required. Short-term: basic skills are advantageous. Flexpatriates: not necessarily required.");
IM(4, 2, "How important is adjustment to the host country for each type of assigned expatriate (long-term, short-term, flexpatriate)?", ["Long-term: very important (incl. family); short-term: important; flex: less important", "Long-term: less important; short-term: important; flex: very important", "Long-term: important; short-term: very important (incl. family); flex: less important", "All three: very important, including adjustment of the family"], "Adjustment matters most when the assignment is long and the family comes too.");
IM(4, 3, "Which feature do corporate (long-term) expatriates, short-term assignees, AND flexpatriates all share?", ["Boundary spanning", "Family relocation", "Pre-departure training", "Repatriation being challenging"], "All three types act as boundary spanners. Integration at the host location, by contrast, is only limited for flexpatriates.");
IM(4, 2, "What are the typical individual motives of a corporate (long-term) expatriate?", ["Career advancement, attractive compensation packages, international experience", "International experience and individual development, without career goals", "Skill transfer, problem-solving, and project-based work", "Avoiding relocation while still gaining some foreign experience"], "Flexpatriates are motivated by international experience and individual development; short-term assignees by experience and career advancement.");
IM(4, 1, "What are the three purposes of expatriate assignments (Edström and Galbraith's classic list)?", ["Position filling, management development, and organization development", "Position filling, knowledge transfer, and cost reduction for the subsidiary", "Management development, network building, and market entry", "Organization development, control, and repatriation planning"], "Ch 4 slide 8.");
IM(4, 2, "A firm sends an engineer to Brazil only because no local engineer has the technical skills to run the new plant. Which purpose of assignment is this?", ["Position filling", "Management development", "Organization development", "Global domestic work"], "Position filling = there is a gap in skills or qualified people at the subsidiary.");
IM(4, 2, "A high-potential manager is rotated to the Singapore subsidiary mainly so she gains international experience for future senior roles. Which assignment purpose is this?", ["Management development", "Position filling", "Organization development", "Flexpatriation"], "Management development builds the individual's skills and career. (Ch 4 slide 8; Ch 7 slide 2)");
IM(4, 2, "An MNE rotates managers through subsidiaries so it builds a shared corporate culture, coordination, and knowledge transfer across units. Which purpose is this?", ["Organization development", "Position filling", "Management development", "Inpatriation"], "Organization development serves the MNE: control, socialization, and a shared global mindset. (Ch 4 slide 8; Ch 7 slide 2)");
IM(4, 2, "The expatriate plays six roles between headquarters and the local unit. Which of these is NOT one of them?", ["Tax auditor", "Agent of direct control", "Language node", "Network builder"], "The six roles: agent of direct control, agent of socialization, network builder, transfer of competence and knowledge, boundary spanner, language node.");
IM(4, 2, "An expatriate translates between head-office English and the subsidiary's local language, so information flows both ways. Which expatriate role is this?", ["Language node", "Agent of direct control", "Agent of socialization", "Network builder"], "The language node role links the shared corporate language with the local language.");
IM(4, 2, "An expatriate makes sure the subsidiary follows headquarters' rules and reports. Which expatriate role is this?", ["Agent of direct control", "Agent of socialization", "Boundary spanner", "Language node"], "Direct control = expatriates make sure headquarters' policies are followed.");
IM(4, 2, "An expatriate spreads the corporate values and culture to local staff so their behavior aligns informally with HQ. Which role is this?", ["Agent of socialization", "Agent of direct control", "Language node", "Position filler"], "Socialization is informal, normative control through shared values.");
IM(4, 2, "An expatriate collects information from the host environment and represents the firm to local stakeholders, crossing organizational boundaries. Which role is this?", ["Boundary spanner", "Language node", "Agent of direct control", "Network builder"], "Boundary spanners work across the boundary between the unit and its environment.");
IM(4, 1, "What is an INPATRIATE?", ["A host- or third-country national transferred into parent-country (HQ) operations", "A parent-country national sent to run a foreign subsidiary for 12+ months", "An employee who lives in one country and commutes to work in another", "An expatriate who has returned home and re-entered headquarters"], "Inpatriation moves HCNs and TCNs into headquarters. (Ch 4 slide 10)");
IM(4, 2, "Which is one of the key drivers for recruiting and transferring inpatriate managers?", ["Building a culturally diverse top team that can 'think global and act local'", "Cutting the cost of expatriate packages by hiring only local staff abroad", "Giving parent-country managers more time abroad in emerging markets", "Keeping strategic decisions inside one national culture at headquarters"], "Ch 4 slide 10: global core competency and diverse perspectives, career opportunities for high-potential HCNs, and difficult emerging-market locations.");
IM(4, 3, "Why do emerging markets help drive the use of inpatriates?", ["They are often hard locations for expatriates (quality of life, cultural adjustment)", "They usually forbid foreign managers from holding top subsidiary jobs by law", "They rarely have high-potential employees who could develop at HQ", "They pay subsidiary managers more than headquarters pays its staff"], "Ch 4 slide 10: inpatriates from those markets can bring local knowledge back without forcing PCNs into hard postings.");
IM(4, 1, "Traditionally, 'expatriate failure' was defined as what?", ["The premature return of an expatriate before the assignment ends", "Poor performance ratings during the first year of the assignment", "Leaving the company within a year after repatriation", "The partner's failure to adjust to the host country"], "Ch 4 slide 11: the classic definition was premature return. The text argues for a broader definition.");
IM(4, 2, "What does Chapter 4 recommend about the definition of expatriate failure?", ["Broaden it beyond premature return to subjective indicators like career or life satisfaction", "Keep it limited to premature return, because that is easy to measure across firms", "Narrow it to the direct cost of the assignment, since subjective indicators are unreliable", "Replace it with turnover after repatriation as the single measure"], "Ch 4 slide 11: numbers must be read with caution, and organizational and individual views may differ.");
IM(4, 2, "Which statement about self-initiated expatriates (SIEs) matches Chapter 4?", ["Many firms do not track or manage them, though mid- to high-status SIEs bring strong skills", "Most are low-status workers, whom firms manage closely through formal expatriate programs", "Firms manage them like corporate expatriates, with full packages and repatriation", "They rarely have language skills, so firms avoid hiring them for global roles"], "Ch 4 slide 12: SIEs often have strong education, language skills, an international mindset, and an entrepreneurial approach.");
IM(4, 2, "The table compares global workers by status. Which group appears at ALL three status levels (low, mid, high)?", ["Migrants", "Corporate expatriates", "Flexpatriates", "Global virtual team members"], "Migrants are marked at low, mid, and high status. Corporate expatriates are mid/high only.", [["Type", "Low", "Mid", "High"], ["Corporate expatriates", "–", "X", "X"], ["Flexpatriates", "–", "X", "(X)"], ["Migrants", "X", "X", "X"], ["Global domestics", "X", "X", "(X)"]]);
IM(4, 3, "When global workers are compared by status, which TWO groups are NOT found at low status?", ["Corporate expatriates and flexpatriates", "Migrants and international commuters", "Self-initiated expatriates and global domestics", "International commuters and migrants"], "Low status is marked only for self-initiated expatriates, international commuters, global domestics, and migrants.");
IT(4, 2, "Flexpatriates usually relocate their families for the duration of each assignment.", false, "Flexpatriates travel without family. (Table 4.2)");
IT(4, 1, "Global virtual team members can do international work without physically relocating.", true, "They work across borders mainly through technology. (Ch 4 slide 13)");
IT(4, 2, "Short-term assignments are usually less cost-intensive than long-term expatriation.", true, "Table 4.2: organizational costs are 'less cost-intensive than long-term expatriation.'");
IT(4, 2, "Chapter 4 says numbers about expatriate failure rates are precise and can be taken at face value.", false, "Ch 4 slide 11: failure figures must be interpreted with caution.");
IT(4, 2, "Even though its definition is debated, presenting expatriate failure as a problem has had a positive effect on attention to expatriation practices.", true, "Ch 4 slide 11.");

/* ===== Chapter 5 — Staffing, Recruitment & Selection ===== */
IM(5, 1, "Which staffing approach fills key subsidiary positions mainly with parent-country nationals (PCNs)?", ["Ethnocentric", "Polycentric", "Geocentric", "Regiocentric"], "Ethnocentric: PCNs are favored for key positions. (Ch 5 slide 2)");
IM(5, 1, "Under which staffing approach do host-country nationals (HCNs) manage subsidiaries, while PCNs hold the top HQ jobs?", ["Polycentric", "Ethnocentric", "Geocentric", "Regiocentric"], "Polycentric: each subsidiary is treated as a distinct national entity run by HCNs.");
IM(5, 1, "Which staffing approach says ability matters more than nationality, so the best person is chosen for the job wherever they come from?", ["Geocentric", "Ethnocentric", "Polycentric", "Regiocentric"], "Geocentric = a worldwide approach to staffing.");
IM(5, 2, "A European MNE moves managers freely among its EU subsidiaries but rarely between Europe and Asia. Which approach is this?", ["Regiocentric", "Geocentric", "Ethnocentric", "Polycentric"], "Regiocentric is like geocentric, but limited to one region.");
IM(5, 2, "A firm uses a PCN to run its new Mexican plant so headquarters keeps tight control and the subsidiary follows MNE policies. Which advantage of PCNs is this?", ["Organizational control and coordination are maintained", "Hiring costs are reduced and no work permit is needed", "Salary requirements are lower than for PCNs", "Language barriers are eliminated"], "Table 5.1: PCN advantages include control and coordination, international experience for promising managers, special skills, and assurance of compliance.");
IM(5, 2, "Which is a DISADVANTAGE of using parent-country nationals (PCNs)?", ["The promotional opportunities of HCNs are limited", "Control of headquarters may be impeded", "The host government may resent hiring them", "They have limited career opportunities outside the subsidiary"], "PCN disadvantages: limited HCN promotion, slow adaptation, an inappropriate HQ style, and different pay for PCNs and HCNs.");
IM(5, 2, "Which is an ADVANTAGE of using third-country nationals (TCNs)?", ["Salary and benefit requirements may be lower than for PCNs", "There is assurance the subsidiary complies with MNE policy", "No work permit is required", "Government policy usually requires hiring TCNs"], "Table 5.1: TCNs may cost less than PCNs and may know the host-country environment better.");
IM(5, 2, "Which is a DISADVANTAGE specific to third-country nationals (TCNs)?", ["Transfers must consider national animosities (e.g., India and Pakistan)", "HCNs see fewer promotion chances in their own subsidiary", "Headquarters may find it harder to control the subsidiary", "Adaptation to the host country may take a long time (and HQ style may not fit)"], "TCN disadvantages also include host-government resentment and TCNs not wanting to return home.");
IM(5, 2, "Which is an ADVANTAGE of hiring host-country nationals (HCNs)?", ["Continuity of management improves, since HCNs stay longer in their jobs", "Headquarters' control and coordination are easier to keep and to monitor", "HCNs gain wide career paths across the whole MNE", "PCNs gain more foreign experience in the subsidiary"], "Table 5.1: HCNs also remove language barriers, reduce hiring costs, may be required by government, and improve HCN morale.");
IM(5, 2, "Which is a DISADVANTAGE of hiring HCNs?", ["It could encourage a federation of national rather than global units", "Language and other barriers with local staff and customers increase sharply", "Hiring costs go up and work permits are required", "Continuity of management gets worse over time"], "Table 5.1: HCN disadvantages include weaker HQ control, limited HCN careers outside the subsidiary, and fewer chances for PCNs to gain foreign experience.");
IM(5, 3, "A host government requires that foreign firms hire local managers. Which staffing group benefits, and which listed advantage does this show?", ["HCNs — 'government policy may dictate hiring of HCNs'", "PCNs — 'assurance of compliance with MNE objectives'", "TCNs — 'better informed about the host environment'", "PCNs — 'promising managers gain international experience'"], "Government pressure is listed as an HCN advantage.");
IM(5, 2, "The determinants of staffing choices fall into four groups. Which is NOT one of them?", ["Shareholder dividend policy", "Context specificities", "Company specificities (structure)", "Local unit specificities"], "The four groups: context specificities, company specificities, local unit specificities, and IHRM practices.");
IM(5, 2, "Among the determinants of staffing choices, 'cultural context, institutional context, staff availability, and type of industry' belong to which group?", ["Context specificities", "Company specificities", "Local unit specificities", "IHRM practices"], "These are features of the external environment.");
IM(5, 2, "Among the determinants of staffing choices, 'establishment method, strategic role and importance, need for control, and locus of decision' belong to which group?", ["Local unit specificities", "Company specificities (MNE-wide)", "Context specificities", "IHRM practices"], "These describe the subsidiary itself (e.g., greenfield vs. acquisition).");
IM(5, 2, "Among the determinants of staffing choices, 'MNE structure and strategy, international experience, corporate governance, and organizational culture' belong to which group?", ["Company specificities", "Context specificities", "Local unit specificities", "IHRM practices"], "These are features of the MNE as a whole.");
IM(5, 2, "Among the determinants of staffing choices, selection, training and development, compensation, and career management are grouped as what?", ["IHRM practices", "Context specificities", "Company specificities", "Local unit specificities"], "IHRM practices also shape which staffing approach is possible.");
IM(5, 2, "How does international recruitment and selection usually differ from domestic recruitment and selection?", ["Fewer external recruits and a preference for internal recruitment", "More external recruits and fewer internal candidates", "A stronger focus on external agencies and job fairs in the host country", "Equal use of internal and external recruits"], "Ch 5 slide 7: internal recruits reduce selection risk and protect present and past human capital investments.");
IM(5, 2, "Why do MNEs prefer internal candidates for international assignments?", ["To reduce selection risk and secure present and past human capital investments", "To meet host-country laws that require internal transfers for all managers", "To avoid paying the allowances that external hires usually ask for", "To skip cross-cultural training, which internal staff do not need"], "Ch 5 slide 7.");
IM(5, 2, "There are six factors in expatriate selection. Which three are INDIVIDUAL factors?", ["Technical ability, cross-cultural suitability, family requirements", "Country/cultural requirements, language, MNE requirements", "Salary, age, gender", "Technical ability, language, and MNE requirements"], "Individual: technical ability, cross-cultural suitability, family requirements. Situational: country/cultural requirements, language, MNE requirements.");
IM(5, 2, "Which factor in expatriate selection is on the SITUATION side of the decision?", ["MNE requirements", "Technical ability", "Cross-cultural suitability", "Family requirements"], "Situational factors: country/cultural requirements, language, MNE requirements.");
IM(5, 2, "Why is technical ability alone NOT enough to select an expatriate?", ["Cross-cultural suitability and family factors also affect success", "Technical ability is hard to measure and so is rarely used", "Host-country laws limit technical tests for foreign managers", "Technical skills matter only for short-term assignments"], "Figure 5.3: technical skill is necessary but not sufficient.");
IM(5, 2, "In the adjustment framework (Festing & Maletzky), what are the three parts, from left to right?", ["Antecedents → modes (strategies of adjustment) → outcomes", "Honeymoon → culture shock → adjustment → mastery (U-curve)", "Selection → pre-departure training → on-assignment", "Individual → job → organizational → non-work"], "Figure 5.4: antecedents (individual, job, organizational, non-work), modes (e.g., coping), and outcomes.");
IM(5, 2, "What are the three adjustment OUTCOMES in the adjustment framework?", ["Interaction adjustment, work adjustment, general adjustment", "Psychological, physical, and financial adjustment abroad", "Ethnocentric, polycentric, geocentric adjustment", "Pre-departure, on-assignment, post-assignment"], "Each outcome has a psychological and a socio-cultural side.");
IM(5, 3, "In the adjustment framework, the ANTECEDENTS of adjustment are grouped into which categories?", ["Individual, job, organizational, non-work", "Technical, cultural, family, language", "Hard, soft, contextual", "Cognitive, affective, behavioral"], "Non-work antecedents include family and spouse factors.");
IM(5, 2, "Which is one of the IHRM solutions for dual-career couples in Chapter 5?", ["Inter-firm networking and job-hunting help for the partner", "Requiring the partner to stay in the home country", "A higher hardship allowance instead of partner support", "Limiting assignments to employees without partners"], "Ch 5 slide 10 also lists work-life support, lessons from Covid-19, managerial support, intra-firm employment, and compensation and benefits.");
IM(5, 2, "An MNE finds the trailing spouse a job inside one of its own subsidiaries in the host country. Which dual-career solution is this?", ["Intra-firm employment", "Inter-firm networking", "Job-hunting assistance", "Managerial support"], "Intra-firm = inside the same MNE. Inter-firm = through other companies' networks.");
IM(5, 2, "Which is a PRE-ASSIGNMENT strategy for MNEs to break the expatriate glass ceiling?", ["Review selection criteria and remove gender bias from selection", "Fulfill the psychological contract after the return", "Keep mentoring and training going throughout the assignment abroad", "Offer short-term assignments as an option on assignment"], "Pre-assignment strategies for MNEs: review criteria, remove bias, train decision-makers, address dual-career issues, and add women to networks.");
IM(5, 3, "Which is a POST-ASSIGNMENT strategy for MNEs to break the expatriate glass ceiling?", ["Fulfill the psychological contract: mentoring and chances to use new expertise", "Review selection criteria and remove gender bias in selection", "Assign women to countries where they can adjust quickly", "Train decision-makers in selection and add women to internal networks"], "On-assignment: country choice, short-term options, mentoring. Post-assignment: honor the psychological contract.");
IM(5, 2, "For female expatriates ON assignment, what is described as a key to breaking the expatriate glass ceiling?", ["Finding and using mentors, and absorbing local knowledge", "Relying mainly on headquarters' instructions and networks", "Avoiding short-term assignments to show long-term commitment", "Keeping a low profile in local business networks"], "Mentors appear in both pre- and on-assignment strategies.");
IM(5, 2, "In an intercultural assessment-center role play, a candidate assumes the business partner's lateness was unintended and does not compare it with home-country habits. Which dimension shows HIGH competence?", ["Non-judgmentalism", "Flexibility", "Tolerance for ambiguity", "Learning orientation"], "Low non-judgmentalism = assuming lateness is intended and praising home-country punctuality.");
IM(5, 2, "In an intercultural assessment-center role play, a candidate stays patient and shows a sense of humor in a confusing situation. Which dimension shows high competence?", ["Tolerance for ambiguity", "Empathy", "Interpersonal skills", "Flexibility (adapting)"], "Low tolerance for ambiguity = impatient, very serious.");
IM(5, 2, "In an intercultural assessment-center role play, when a meeting stalls, a candidate changes the subject and suggests a new meeting. Which dimension shows high competence?", ["Flexibility", "Non-judgmentalism", "Empathy", "Learning orientation"], "Low flexibility = repeating continuously, talking about wasted opportunities.");
IM(5, 3, "In an intercultural assessment-center role play, a candidate speaks immediately about business and says 'goodbye' quickly. This shows LOW competence on which dimension?", ["Interpersonal skills", "Tolerance for ambiguity", "Learning orientation", "Flexibility"], "High interpersonal skills = using the time for a short conversation and speaking about oneself or private matters.");
IM(5, 2, "In an intercultural assessment-center role play, a candidate asks to clarify unclear issues and takes the other side's arguments into account. Which dimension is this?", ["Learning orientation", "Empathy", "Non-judgmentalism", "Tolerance for ambiguity"], "Low learning orientation = not asking for clarification or ignoring the partner's point.");
IT(5, 1, "Under a geocentric staffing approach, nationality matters more than ability.", false, "Geocentric = ability matters more than nationality.");
IT(5, 2, "One disadvantage of TCNs is that they may not want to return to their home country after the assignment.", true, "Table 5.1.");
IT(5, 2, "Hiring HCNs limits opportunities for PCNs to gain foreign experience.", true, "Table 5.1, HCN disadvantages.");
IT(5, 2, "A disadvantage of PCNs is that compensation for PCNs and HCNs may differ, which can create tension.", true, "Table 5.1, PCN disadvantages.");
IT(5, 2, "International recruitment typically uses MORE external recruits than domestic recruitment.", false, "It uses fewer external recruits and prefers internal candidates. (Ch 5 slide 7)");
IT(5, 2, "In the adjustment framework, each adjustment outcome has both a psychological and a socio-cultural side.", true, "Figure 5.4.");

/* ===== Chapter 6 — Global Performance Management ===== */
IM(6, 2, "Which is one of the MNE performance management constraints?", ["Whole vs. part", "Ethnocentric staffing", "Dual-career couples", "Language training"], "Ch 6 slide 3: whole vs. part, non-comparable data, volatility, separation by time and distance, and variable market maturity.");
IM(6, 2, "A subsidiary looks unprofitable on paper, but it exists to block a competitor in its home market, which helps the MNE overall. Which constraint does this show?", ["Whole vs. part", "Non-comparable data", "Volatility of the environment", "Separation by time and distance"], "A unit's results must be judged by its role in the MNE's global strategy, not in isolation.");
IM(6, 2, "Sales and productivity figures from a subsidiary in Germany can't be compared directly with ones from Brazil because of different accounting rules, labor laws, and markets. Which constraint is this?", ["Non-comparable data", "Whole vs. part", "Variable levels of maturity", "Separation by time and distance"], "Data from different countries often can't be compared like-for-like.");
IM(6, 2, "Sudden currency swings, political instability, and new trade rules make long-term subsidiary goals unrealistic. Which constraint is this?", ["Volatility in the global business environment", "Variable levels of maturity across markets", "Non-comparable data between subsidiaries", "Separation by time and distance from HQ"], "Ch 6 slide 3.");
IM(6, 2, "Headquarters managers are 10 time zones away and rarely visit, which makes it hard to judge subsidiary performance. Which constraint is this?", ["Separation by time and distance", "Volatility in the global environment", "Whole vs. part (global strategy)", "Non-comparable data across units"], "Ch 6 slide 3.");
IM(6, 3, "A new subsidiary in an emerging market can't be held to the same targets as a 30-year-old subsidiary in a mature market. Which constraint is this?", ["Variable levels of maturity across markets", "Volatility in the global environment", "Whole vs. part (the unit's global role)", "Separation by time and distance"], "Ch 6 slide 3: comparative data must be relevant to each market's stage.");
IM(6, 2, "In MNE control and performance, formal and informal control activities focus on which three things?", ["Standardization of practices, socialization, and compliance with norms/values", "Hard goals, soft goals, and contextual goals for each subsidiary manager", "Funneling, summation, conversion, and sharpening of performance results", "Selection, pre-departure training, and repatriation of key managers"], "These lead to a global mix of strategic outcomes for HQ and the subsidiary.");
IM(6, 2, "There are five variables affecting expatriate performance. Which is NOT one of them?", ["The expatriate's age", "The compensation package", "Headquarters' support", "Cultural adjustment of self and family"], "The five: compensation package, task, headquarters' support, host environment, cultural adjustment (self and family).");
IM(6, 2, "An expatriate performs poorly mainly because his spouse and children are unhappy and unsettled in the host country. Which variable affecting expatriate performance is at work?", ["Cultural adjustment of self and family", "The task (assignment variables, role)", "The compensation package", "Headquarters' support for the assignee"], "Family adjustment is part of the outermost layer in Figure 6.3.");
IM(6, 2, "Which type of international assignment is short-term knowledge transfer, with little cultural adjustment needed?", ["Technical", "Developmental", "Strategic", "Functional"], "Ch 6 slide 7.");
IM(6, 2, "An assignment focused on in-country performance and the assignee's own learning of local conditions (often part of a career program) is which type?", ["Developmental", "Technical", "Strategic (high-profile)", "Functional"], "Developmental = in-country performance plus local understanding for the assignee.");
IM(6, 2, "A high-profile assignment to open a new market, mainly to build the manager's global perspective, is which type?", ["Strategic", "Technical", "Functional", "Developmental"], "Strategic = high-profile activities for developing a global perspective.");
IM(6, 3, "Which assignment type involves a more enduring two-way transfer of existing processes and practices between HQ and the subsidiary?", ["Functional", "Technical", "Developmental", "Strategic"], "Functional assignments need more cultural adjustment because the assignee works closely with locals.");
IM(6, 2, "In the PCN role conception model, who is the ROLE SENDER that communicates the role conception to the PCN manager?", ["The multinational (headquarters)", "Host-country stakeholders only", "The PCN's family", "The local union"], "Host-country stakeholders are also role senders, across a cultural boundary.");
IM(6, 3, "How does the TCN role conception differ from the PCN role conception?", ["The TCN faces TWO cultural boundaries: with the parent company and with host stakeholders", "The TCN faces one cultural boundary, the same one a PCN faces with host stakeholders", "The TCN receives the role conception only from host-country stakeholders", "The TCN acts as the role sender for the parent company in the host country"], "TCNs come from neither the parent nor the host country, so role expectations cross more boundaries.");
IM(6, 2, "Why does the role conception model matter for appraising expatriates?", ["HQ and host expectations can conflict across a cultural boundary, so HQ-approved behavior may look wrong locally", "Expatriates mainly face role overload from both sides, so the number of goals should be cut in half", "It shows that host-country stakeholders should set all goals for the expatriate alone", "It shows that one standard form works the same way in every subsidiary"], "Role conflict and ambiguity can make performance hard to judge fairly.");
IM(6, 2, "Which is a performance management challenge for NON-expatriates (e.g., flexpatriates, commuters, virtual team members)?", ["Isolating the international dimensions of job performance is not as straightforward", "Their performance is easy to isolate because they spend so little time abroad", "They are appraised only by host managers, so HQ has no say", "Cultural differences do not affect their performance criteria"], "Ch 6 slide 10 also lists cultural differences in criteria, outside appraisers, unclear rewards, and impact on HCN co-workers.");
IM(6, 1, "What are the three types of criteria (goals) used in appraising expatriate performance?", ["Hard, soft, and contextual goals", "Ethnocentric, polycentric, and geocentric goals", "Technical, developmental, and strategic goals", "Short, medium, and long goals"], "Ch 6 slide 11.");
IM(6, 2, "Return on investment, market share, and sales growth are examples of which goal type?", ["Hard goals", "Soft goals", "Contextual goals", "Developmental goals"], "Hard goals are objective, quantifiable, and directly measurable.");
IM(6, 2, "Leadership style and interpersonal skills are examples of which goal type?", ["Soft goals", "Hard goals", "Contextual goals", "Functional goals"], "Soft goals are relationship- or trait-based and harder to measure.");
IM(6, 3, "Which goal type tries to account for situational factors outside the expatriate's control, like local market conditions?", ["Contextual goals", "Hard goals", "Soft goals", "Strategic goals"], "Contextual goals take the performance context into account.");
IM(6, 2, "Which is one of the key questions around international performance appraisal?", ["Who conducts the appraisal: host managers, home managers, or both?", "Should the appraisal use hard goals only, with no soft goals?", "Should HQ stop appraising expatriates while they are abroad?", "Which currency should be used to pay the performance bonus?"], "Ch 6 slide 12: who appraises, standardized vs. customized forms, frequency, how to give feedback, and cultural applicability.");
IM(6, 3, "Why might a host-country manager and a home-country manager rate the same expatriate differently?", ["The host manager sees daily behavior through a local lens; the home manager is distant and misses context", "The home manager sees more daily behavior, while the host manager only sees the yearly results", "The host manager uses only hard goals, while the home manager uses only soft goals", "They use the same criteria and the same cultural lens, so any gap is only random error"], "This is why many firms combine raters.");
IM(6, 2, "In the strategic global performance management (GPM) cycle, what are the four steps of TRANSFORMATION?", ["Funneling, summation, conversion, sharpening", "Planning, doing, checking, and acting", "Selection, training, appraisal, reward", "Hard, soft, contextual, strategic"], "Phase II of the GPM cycle (Engle, Festing & Dowling).");
IM(6, 3, "In the strategic global performance management (GPM) cycle, 'strategic actions' (Phase III) include decisions at which levels?", ["Organizational, unit, and individual", "Local, regional, and global only", "Hard, soft, and contextual", "Technical, functional, and strategic"], "Results are transformed, reported and reviewed, then acted on at all three levels, followed by revisions to GPM systems (Phase IV).");
IM(6, 2, "Which are ORGANIZATIONAL outcomes (consequences) of MNE performance management?", ["Control, reputation, and legal compliance", "Training, career implications, and financial consequences", "Funneling and sharpening", "Language and culture"], "Individual outcomes = training, career implications, financial consequences.");
IM(6, 2, "Which are INDIVIDUAL outcomes (consequences) of MNE performance management?", ["Training, career implications, financial consequences", "Control, reputation, and legal compliance", "Standardization, socialization, and compliance", "Funneling, summation, and sharpening"], "Figure 6.1.");
IM(6, 3, "Which set lists the 'critical issues' in MNE performance management?", ["Criteria (implicit/explicit; person, activities, outcomes), purposes (developmental, pay), tasks/roles, timing", "Control, reputation, and legal compliance at the organizational level, plus training at the individual level", "Funneling, summation, conversion, and sharpening of results, followed by strategic actions and revisions", "Whole vs. part, non-comparable data, volatility, separation by time and distance, and market maturity"], "Figure 6.1.");
IT(6, 2, "A standardized global appraisal form always works equally well in every culture.", false, "Ch 6 slide 12 raises the question of cultural applicability; formats may need customizing.");
IT(6, 2, "Hard goals are usually easier to measure objectively than soft goals.", true, "Hard = quantifiable; soft = relationship or trait based.");
IT(6, 2, "Technical assignments usually require MORE cultural adjustment than functional assignments.", false, "Technical assignments are short-term knowledge transfer; functional ones involve enduring two-way transfer with locals.");
IT(6, 2, "Headquarters' support is one of the variables that affects expatriate performance.", true, "Figure 6.3.");
IT(6, 2, "Performance criteria can be subject to cultural differences, which complicates appraisal of non-standard international work.", true, "Ch 6 slide 10.");

/* ===== Chapter 7 — International Training, Development & Careers ===== */
IM(7, 2, "Which is an ORGANIZATIONAL development outcome of international assignments?", ["The MNE accumulates knowledge and abilities and gains a global mindset", "Individuals gain experience and advance their own careers", "The MNE gets a cadre of experienced international operators to deploy", "Host governments gain trained local managers at no cost"], "Ch 7 slide 2: the MNE also gains direct control and socialization, which helps knowledge and competence transfer.");
IM(7, 2, "Which is a MANAGEMENT development outcome of international assignments?", ["Individuals gain experience and careers; the MNE gets a cadre of international operators", "The MNE accumulates knowledge and abilities and gains a global mindset", "The MNE gets direct control and socialization, which helps knowledge transfer later", "Host units get standard systems, and HCNs take over sooner"], "Ch 7 slide 2.");
IM(7, 2, "How is the international assignment itself a training and development tool?", ["Expatriates train HCNs, ensure systems are adopted, and develop as managers themselves", "Expatriates replace local trainers, so HCNs need no further training", "Expatriates mainly monitor costs and report the subsidiary's results back to headquarters", "Expatriates learn the local language, which is the main training outcome"], "Expatriates are trainers, ensure adoption, and develop through job rotation.");
IM(7, 2, "Which is one of the essential components of pre-departure training?", ["Preliminary visits", "Exit interviews", "Stock option grants", "Performance calibration"], "Ch 7 slide 5: cultural awareness programs, preliminary visits, language training, practical day-to-day help, and security briefings.");
IM(7, 2, "A company sends the expatriate and spouse to the host city for a week before the move to look at housing and schools. Which pre-departure component is this?", ["Preliminary visit", "Cultural awareness program", "Security briefing", "Language training"], "Preliminary visits give a first-hand look and help the family decide and prepare.");
IM(7, 2, "Help with finding housing, schools, and a bank account in the host country is which pre-departure component?", ["Practical assistance with day-to-day matters", "A cultural awareness program", "A preliminary visit to the host city and its schools", "A security briefing before departure"], "Ch 7 slide 5.");
IM(7, 2, "Mendenhall and Oddou's model links which three keys of cross-cultural training (CCT)?", ["Training methods, levels of training rigor, and duration of training", "Training methods, language level, and the trainee's personality", "Training rigor, cost of training, and timing before departure", "Duration of training, trainer nationality, and family involvement"], "Ch 7 slide 6.");
IM(7, 2, "In the Mendenhall–Oddou model, 'culture novelty' means what?", ["How different the host culture is from the expatriate's native culture", "How new the employee is to the firm and to international work", "How recently the subsidiary in the host country was opened", "How much interaction with host nationals the job will need each day"], "Ch 7 slide 6.");
IM(7, 2, "An employee will spend 3 weeks in a culture similar to home, with low interaction with locals. Which CCT approach fits best?", ["Information-giving approach", "Affective approach", "Immersion approach", "No training is ever useful"], "Information-giving: low rigor, under 1 week, area/cultural briefings, films and books, survival-level language. (Ch 7 slide 8)");
IM(7, 2, "Which CCT approach uses role-playing, critical incidents, culture assimilator training, case studies, and stress reduction training?", ["Affective approach", "Information-giving approach", "Immersion approach", "Preliminary-visit approach"], "Affective: moderate rigor, 1–4+ weeks, for 2–12 month stays with some interaction. (Ch 7 slide 9)");
IM(7, 2, "Which CCT approach uses assessment centers, field experiences, simulations, sensitivity training, and extensive language training?", ["Immersion approach", "Affective approach", "Information-giving approach", "Survival approach"], "Immersion: high rigor, 1–2+ months, for 1–3 year stays with high interaction in a novel culture. (Ch 7 slide 10)");
IM(7, 3, "A manager will live in a very unfamiliar culture for 2 years and work closely with locals every day. What CCT approach and training length fit Mendenhall et al.'s model?", ["Immersion, about 1–2+ months of training", "Information-giving, less than a week", "Affective, 1–4 weeks", "No training needed for long stays"], "High interaction plus high culture novelty calls for high rigor.");
IM(7, 3, "In the Mendenhall, Dunbar and Oddou CCT model, what length of training goes with the AFFECTIVE approach?", ["1–4 weeks", "Less than a week", "1–2 months or more", "1–3 years"], "Information-giving < 1 week; affective 1–4 weeks; immersion 1–2+ months.", [["Approach", "Rigor", "Training length", "Length of stay"], ["Information-giving", "Low", "?", "1 month or less"], ["Affective", "Moderate", "?", "2–12 months"], ["Immersion", "High", "?", "1–3 years"]]);
IM(7, 2, "Which study of pre-departure training effectiveness was a META-ANALYSIS of the cross-cultural training literature?", ["Morris and Robie", "Brookfield surveys", "Eschbach et al.", "Mendenhall and Oddou"], "Brookfield = self-evaluated survey responses; Eschbach et al. = measured cognitive, affective, and experiential CCT and language training. (Ch 7 slide 11)");
IM(7, 2, "Which is one of the reasons networked MNEs use international teams?", ["To foster innovation, learning, and knowledge transfer across boundaries", "To centralize decisions at HQ and reduce the need for local input", "To replace expatriate assignments with lower-cost virtual work", "To keep national units separate so each can act on its own"], "Teams also encourage diverse decision-making, develop a global perspective, and build shared values (normative control).");
IM(7, 2, "When international teams are developed through international assignments, the assignments feed into which outcomes?", ["Individual development, an international cadre, and international teams, leading to organizational development", "Lower costs, fewer expatriates, and more virtual teams, leading to a smaller headquarters staff", "Hard goals, soft goals, and contextual goals, leading to better performance appraisal", "Pre-departure training, home leave, and re-entry, leading to smoother repatriation"], "Figure 7.2.");
IM(7, 2, "Which is a training and development TREND in Chapter 7?", ["Host countries continue to pressure for local training and development", "Interest in training and development focused on China is declining", "NGOs are becoming less important in training and development", "Competence learning no longer depends on national context"], "Ch 7 slide 14.");
IM(7, 1, "'Expatriation includes repatriation' describes which sequence?", ["Recruitment & selection → pre-departure training → on-assignment → re-entry or reassignment", "Pre-departure training → recruitment & selection → on-assignment → re-entry", "Recruitment & selection → on-assignment → appraisal → termination when the posting ends", "On-assignment → re-entry → pre-departure training → recruitment & selection"], "Repatriation is part of the expatriation cycle, and re-entry can loop back to a new assignment.");
IM(7, 2, "Which is a PRE-DEPARTURE repatriation activity or practice?", ["A sponsor is assigned", "Home leave", "Rituals to share experience", "New assignment"], "Pre-departure: sponsor, communication protocols, web/media contacts, pre-departure training and orientation.");
IM(7, 2, "Which is a DURING-ASSIGNMENT repatriation activity or practice?", ["Home leave and ongoing communication with the sponsor", "Assigning a sponsor and setting communication protocols", "Organizational reconnection and a new assignment", "Rituals or ceremonies to share the experience"], "During assignment: home leave, work-related information exchanges, communication with the sponsor, systematic pre-return orientation.");
IM(7, 2, "Which is an UPON-RETURN repatriation activity or practice?", ["Organizational reconnection and help with non-work factors", "Pre-departure training and orientation for the family", "Communication protocols and web and media contacts", "Home leave and work-related information exchanges"], "Upon return: new assignment, organizational reconnection, help with non-work factors, rituals to share the experience.");
IM(7, 2, "What is the shock an expatriate feels when coming HOME called?", ["Culture shock back (reverse culture shock)", "Culture shock out (departure shock)", "The honeymoon phase of the U-curve", "Role conflict across a cultural boundary"], "Culture shock out happens on departure; culture shock back happens on return. The goal is a balanced, integrated global perspective.");
IM(7, 2, "Career anxiety (loss of visibility, no post-assignment guarantee, workplace changes) is which kind of factor in repatriate adjustment?", ["Job-related factor", "Social factor", "Family factor", "Host-country factor"], "Job-related factors also include work adjustment, coping with new role demands, and loss of status and pay.");
IM(7, 2, "Which is a SOCIAL factor influencing repatriate adjustment?", ["Effect on the partner's career", "The re-entry position offered", "Loss of status and pay on return", "Devaluing of the experience abroad"], "Social factors: family adjustment, social networks, effect on the partner's career.");
IM(7, 2, "A repatriate returns to find her new job uses none of her international skills and her experience is ignored. Which repatriate adjustment factor is this?", ["Work adjustment (devaluing experience, re-entry position)", "Social factors (family adjustment, social networks)", "Loss of status and pay (the allowance ends)", "Culture shock out (departure from home)"], "Work adjustment covers the re-entry position, the employment relationship, and devaluing experience.");
IM(7, 2, "When the repatriation process is linked to outcomes, which outcomes does it affect?", ["Staff availability and retention, employment relationship, organizational commitment, knowledge sharing", "Host-country integration, family adjustment, language skills, and hardship allowances for new assignees", "Hard goals, soft goals, contextual goals, and the frequency of performance appraisal", "Ethnocentric, polycentric, geocentric, and regiocentric staffing choices across subsidiaries"], "The value the firm places on international experience shapes how it manages repatriation.");
IM(7, 2, "Which of these is 'market-specific knowledge' gained from an international assignment?", ["Knowledge of local political, social, and economic systems, language, and customs", "Intercultural knowledge, self-confidence, flexibility, and tolerance for differences", "Communication, project management, and problem-solving skills", "Broader job responsibilities and exposure to other parts of the firm"], "Ch 7 slide 19: also personal skills, job-related management skills, network knowledge, and general management capacity.");
IM(7, 2, "A repatriate came back more self-confident, flexible, and tolerant. Which knowledge/skill category is this?", ["Personal skills", "Market-specific knowledge", "Network knowledge", "General management capacity"], "Personal skills = intercultural knowledge, self-confidence, flexibility, tolerance.");
IM(7, 2, "Broader job responsibilities and exposure to other parts of the organization build which capability?", ["General management capacity", "Market-specific knowledge", "Personal skills", "Network knowledge"], "Ch 7 slide 19.");
IM(7, 2, "Which topic is covered by a repatriation program?", ["Reverse culture shock, including family disorientation", "Cultural dimensions of the next host country", "Pre-departure language training for the next posting", "Performance appraisal forms used at headquarters"], "Table 7.3 also covers relocation, financial and tax help, re-entry position, schooling, workplace changes, stress management, and networking.");
IM(7, 2, "In a repatriation program, 'financial and tax assistance' specifically deals with which issue?", ["Loss of the overseas allowance and changes in benefits and taxes", "Help investing the savings made during the assignment abroad", "Pay for host-country nationals who replace the expatriate", "Host-country tax filings for the subsidiary's local staff"], "Repatriates often take a pay drop when allowances end.");
IM(7, 2, "Which is one of the strategies for smooth re-entry?", ["Written repatriate agreements clarifying assignments upon return", "Ending contact with the expatriate so they can focus abroad", "Waiting until the return to discuss the next job", "Stopping mentoring when the expatriate leaves for the posting"], "Ch 7 slide 21 also lists briefings, career planning sessions, mentoring after return, home visits, reorientation, financial advice, an adjustment period, and visible signs of the repatriate's value.");
IM(7, 3, "A firm wants repatriates to stay after returning. Which combination best fits the strategies for smooth re-entry?", ["Mentoring after return, multiple career planning sessions, and visible signs of the repatriate's value", "A lateral 'holding' job while HQ decides, plus a short welcome-back meeting on the first day", "Ending the allowance early, plus a standard orientation shared with new hires", "Letting the repatriate find their own next role, plus one exit-style interview"], "Ch 7 slide 21.");
IT(7, 2, "The information-giving approach is the most rigorous form of cross-cultural training.", false, "It is the least rigorous (low rigor, under a week).");
IT(7, 2, "Repatriation is part of the expatriation process, not a separate event after it.", true, "Figure 7.3: expatriation includes repatriation.");
IT(7, 2, "Loss of status and pay is a job-related factor that can make repatriate adjustment harder.", true, "Figure 7.5.");
IT(7, 2, "Security briefings are one of the essential components of pre-departure training.", true, "Ch 7 slide 5.");
IT(7, 2, "In Mendenhall and Oddou's model, a higher expected degree of interaction and greater culture novelty call for more rigorous and longer training.", true, "Ch 7 slides 6–10.");
IT(7, 2, "International teams can act as informal, normative control by developing shared values through socialization.", true, "Ch 7 slide 12.");


/* ===== From the predicted Exam 2 study guide (Study Quest/MGMT 660 Exam 2 Study Guide (Ch 4-7).pdf):
   application questions, mini-cases, and essay angles. "(text)" = general textbook knowledge, not on the slides. ===== */
// Ch 4
IM(4, 3, "Compare a corporate expatriate with a flexpatriate on the taxonomy of global work. Which is correct?", ["Corporate expatriate: highest non-work disruption (family moves); flexpatriate: highest physical mobility (frequent trips)", "Corporate expatriate: highest physical mobility; flexpatriate: highest non-work disruption from relocating the family", "Both have identical scores on all three dimensions", "Flexpatriates need no cognitive flexibility at all"], "After one move, an expatriate's mobility is low, but family disruption is high. Flexpatriates travel constantly; their family disruption is repeated absences, not relocation. (Study guide, Ch 4)");
IM(4, 2, "What kind of HR support do flexpatriates need most, given their global work profile?", ["Travel-health, work-life, and scheduling support", "Family relocation and help finding schools", "Immersion-level language and culture training", "A formal repatriation program and sponsor"], "Match support to the profile: expatriates need family/relocation help; flexpatriates need help with the travel load. (Study guide, Ch 4)");
IM(4, 3, "(text) Harzing gives the expatriate control roles animal names. Which pairing is right?", ["Bears = direct control; bumble-bees = socialization; spiders = network building", "Bears = network building; spiders = direct control; bumble-bees = language", "Bumble-bees = direct control; bears = socialization; spiders = boundary spanning", "Spiders = socialization; bears = knowledge transfer; bumble-bees = control"], "Harzing's metaphor (text — check your book). (Study guide, Ch 4)");
IM(4, 3, "A firm has just acquired a foreign subsidiary. Which expatriate roles should come FIRST?", ["Direct control (compliance, reporting, integration), then socialization and knowledge transfer", "Network building first, then direct control once local ties and trust are strong enough", "Language node first, then boundary spanning with local stakeholders", "Boundary spanning first, then socialization through shared values"], "Control first, then culture and systems. Over time move toward network building and boundary spanning so local managers can take over. (Study guide, Ch 4)");
IM(4, 2, "(text) What is the MOST cited cause of expatriate failure?", ["The partner's (spouse's) inability to adjust", "The expatriate's lack of technical skill", "Too much pay", "The host country's weather"], "Other causes: family issues, the manager's own poor adjustment, job dissatisfaction. (Study guide, Ch 4 — text)");
IM(4, 3, "(text) Why did Harzing call high expatriate failure rates a 'myth'?", ["The widely quoted high rates came from old, poorly sourced studies", "Newer studies showed failure rates are even higher than reported", "Failure rates cannot be measured, so firms should stop counting", "Only flexpatriates and commuters return early from assignments"], "The slides agree: failure numbers must be interpreted with caution. (Study guide, Ch 4)");
IM(4, 3, "Which is a reason premature return is TOO NARROW as a definition of expatriate failure?", ["Staying but underperforming, or quitting after return, are failures too; some early returns are successes", "Premature return is rare today, so the definition counts too few failures to be useful to firms", "It counts successful expatriates as failures when they extend their assignment", "It already includes turnover after repatriation, so it double-counts failures"], "Broaden the definition and add subjective indicators such as career and life satisfaction. (Study guide, Ch 4)");
IM(4, 2, "Which is an INDIRECT cost of expatriate failure?", ["Lost relationships, market share, reputation, and HCN morale", "Relocation expenses and the salary already paid out", "The cost of sending, training, and settling a replacement", "Pre-departure training paid for the failed assignee"], "Direct costs: relocation, salary, replacement. Indirect: relationships, market share, reputation, morale. (Study guide, Ch 4)");
IM(4, 2, "(text) Which is a challenge that inpatriates face?", ["Adjusting to HQ culture as a minority and feeling like an outsider in two places", "Getting the highest status at HQ, which makes local peers resent and avoid them", "Losing all contact with headquarters while they work in the host unit", "Having no need for return or next-role planning after the transfer"], "The firm must also plan the inpatriate's return or next role. (Study guide, Ch 4 — text)");
IM(4, 2, "How are self-initiated expatriates usually employed, compared with assigned expatriates?", ["On a local contract, with no expatriate package or planned repatriation", "On a full expatriate package, with a guaranteed job when they return", "As flexpatriates, on short trips paid by the home-country employer", "By their home-country employer, on a short-term assignment contract"], "SIEs are a lower-cost source of global skills — if the firm tracks and manages them. (Study guide, Ch 4)");
IM(4, 3, "When global workers are compared by status, what is a HORIZONTAL comparison?", ["Comparing status levels (low, mid, high) within one type of global worker", "Comparing different types of global workers at the same status level", "Comparing how status changes as an assignment gets longer", "Comparing the status of PCNs, HCNs, and TCNs in one subsidiary"], "Vertical = across types of global workers. (Study guide, Ch 4)");
IM(4, 3, "Mini-case: a Houston firm must install an ERP module at its Monterrey subsidiary over six weeks. Which global worker fits best?", ["Flexpatriate (technical transfer, family stays home)", "Corporate long-term expatriate, with family relocated", "Inpatriate brought to the Houston headquarters", "Global domestic working only from Houston"], "If the work ran past ~3 months, a short-term assignee would fit. (Study guide mini-case)");
IM(4, 3, "Mini-case: the same firm needs a general manager for its São Paulo subsidiary for three years, and no strong Brazilian HCN exists. What fits best?", ["Corporate (long-term) expatriate with family support, immersion CCT, and a repatriation plan", "Flexpatriate with monthly visits, survival-level language training, and no family move", "Global virtual team member who manages the subsidiary from Houston by video", "International commuter who flies in each week and keeps the family in Houston"], "Highest cost and failure risk, but needed for control and development. (Study guide mini-case)");
IM(4, 3, "Mini-case: coordinating a product launch in five EU countries with monthly site visits for a year fits which approach?", ["Business traveler/flexpatriate plus a global virtual team, with contextual goals", "One long-term expatriate in each of the five countries, with family support", "Five inpatriates brought to Houston for the full year of the launch", "Polycentric HCN hiring in each country, with no coordination role"], "The home office stays the base; give work-life support for the travel load. (Study guide mini-case)");
// Ch 5
IM(5, 2, "(text) Ethnocentric, polycentric, geocentric, and regiocentric orientations are associated with which author?", ["Perlmutter", "Hofstede", "Edström & Galbraith", "Mendenhall & Oddou"], "EPRG — firms often mix orientations by function and subsidiary. (Study guide, Ch 5 — text)");
IM(5, 2, "Ethnocentric staffing fits best when…", ["The firm is early in internationalizing, needs strong control, or must protect key technology", "The firm follows a multidomestic strategy that needs high local responsiveness in each market", "The firm wants a transnational strategy built on global learning and mobility", "The firm runs a regional HQ and moves managers only inside that region"], "Main risk: HCN resentment, a 'glass ceiling' for locals, poor local fit. (Study guide, Ch 5)");
IM(5, 2, "Polycentric staffing fits best with which strategy?", ["Multidomestic strategy with high local responsiveness", "Transnational strategy with global integration", "Early internationalization with tight control", "A purely domestic strategy"], "Main risk: a gap between HQ and subsidiaries — a 'federation' of national units. (Study guide, Ch 5)");
IM(5, 2, "What is a main RISK of geocentric staffing?", ["Cost, immigration rules, and complex pay", "A federation of national units", "An HCN glass ceiling and resentment", "Regional silos that block HQ careers"], "Geocentric fits a transnational strategy. (Study guide, Ch 5)");
IM(5, 2, "What is a main risk of regiocentric staffing?", ["Regional silos: staff rarely reach global HQ", "A federation of separate national units", "An HCN glass ceiling in every subsidiary", "Cost and immigration limits worldwide"], "Regiocentric fits a regional strategy (e.g., an EU HQ). (Study guide, Ch 5)");
IM(5, 3, "Using the determinants of staffing choices, which example would push a firm TOWARD HCNs?", ["A host-country law requiring local hiring (context specificity)", "No local talent available", "A centralized culture with little international experience", "A strategic R&D hub that needs tight control"], "The other options push toward PCNs/TCNs. (Study guide, Ch 5)");
IM(5, 3, "An acquired subsidiary already has capable local managers. Which group of staffing determinants points toward keeping HCNs?", ["Local unit specificities (establishment method)", "Company specificities (MNE structure)", "IHRM practices (career management)", "Context specificities (staff availability)"], "Greenfield vs. acquisition is the establishment method. (Study guide, Ch 5)");
IM(5, 2, "(text) What is the risk of 'coffee-machine' selection for international assignments?", ["Managers pick people they know informally, which excludes women and outsiders", "Candidates are chosen by formal tests that ignore cross-cultural suitability", "Only external candidates are hired, which raises selection risk for the MNE", "The partner decides on the assignment, which shrinks the candidate pool"], "Internal, informal selection can bias the pool. (Study guide, Ch 5 — text)");
IM(5, 3, "Why do firms tend to over-weight technical ability in expatriate selection?", ["It is easy to measure and job-related, so it feels safe and lowers selectors' risk", "It is the main cause of expatriate failure, so selectors focus on it first", "Family factors may never be discussed in selection in most countries", "Cross-cultural suitability cannot be assessed by any known method"], "But family and cross-cultural problems cause most failures; technical skill is necessary but not sufficient. (Study guide, Ch 5)");
IM(5, 2, "Which is a BETTER practice for expatriate selection than technical skill alone?", ["Structured interviews, cultural-intelligence measures, realistic previews, partner input, assessment centers", "Choosing volunteers first, then the most senior volunteer, with a technical test as the tiebreak", "Choosing by seniority and past domestic performance, with the manager's informal recommendation", "Relying on the candidate's self-rating of cultural skills plus a short technical interview"], "(Study guide, Ch 5)");
IM(5, 2, "(text) What are the four phases of the U-curve of adjustment?", ["Honeymoon → culture shock → adjustment → mastery", "Selection → training → assignment → return", "Antecedents → modes → outcomes → feedback", "Shock out → shock back → reconnection → promotion"], "Research support is mixed; use it as a description, not a rule. (Study guide, Ch 5 — text)");
IM(5, 3, "In the adjustment framework, which is the difference between the psychological and socio-cultural side of an outcome?", ["Psychological = well-being; socio-cultural = skill at fitting in", "Psychological = work; socio-cultural = family", "Psychological = before departure; socio-cultural = after return", "There is no difference"], "Each of interaction, work, and general adjustment has both sides. (Study guide, Ch 5)");
IM(5, 2, "Why are dual-career couples a STRATEGIC IHRM issue?", ["Partners refuse assignments and partner dissatisfaction causes failure, shrinking the pool", "Partners usually want to relocate, so the issue is only the cost of moving the family", "Dual-career couples are barred from assignments by law in most host countries", "The issue affects only domestic hiring, not international assignments"], "The pool shrinks especially for women, whose male partners are often less willing to follow. (Study guide, Ch 5)");
IM(5, 3, "(text) Which is one of Adler's myths about women in international management?", ["Foreigners will not accept women managers", "Women are more likely to be selected than men", "Host nationals always see a woman as a woman first", "Firms always send women abroad"], "Evidence: women are as interested as men, and host nationals often see a woman as a foreigner first. The main barrier is HQ selection bias. (Study guide, Ch 5 — text)");
IM(5, 2, "Insch, McIntyre & Napier describe the expatriate glass ceiling as what?", ["A 'second layer of glass' on top of the domestic glass ceiling", "A ceiling on the number of assignments any one person can take", "A rule that limits expatriate pay to the level of local managers", "A barrier that affects male and female expatriates the same way"], "Table 5.6 gives pre-, on-, and post-assignment strategies. (Study guide, Ch 5)");
IM(5, 2, "What makes an intercultural assessment center different from a self-report test?", ["Trained observers score behavior in role plays and simulations", "Candidates rate their own intercultural skills on a long survey", "It measures mainly technical ability in timed job simulations", "It is done after the assignment to decide on the next posting"], "It scores six dimensions, e.g., tolerance for ambiguity and non-judgmentalism. (Study guide, Ch 5)");
IM(5, 3, "Mini-case: a U.S. medical-device firm opens its first plant in Vietnam. Incentives favor local hiring, but HQ worries about quality control. What staffing path fits the first five years?", ["PCN plant head + HCN deputy (+ Malaysian TCNs) at first, then localize as HCNs prove themselves", "All HCNs from day one, with HQ control through monthly reports and audits from headquarters only", "All PCNs permanently, so that quality control never depends on local managers", "Only flexpatriates, who fly in for short visits and leave the plant to local staff"], "Start mostly ethnocentric for control, then move polycentric/regiocentric, keeping informal control through socialization. (Study guide mini-case)");
IM(5, 3, "In the Vietnam mini-case, why use Malaysian TCNs for the technical ramp-up?", ["They cost less than PCNs and have relevant regional experience", "They remove host-government concerns about foreign managers", "They plan to return home soon, so turnover risk is low", "They share HQ's culture exactly, so control is easy"], "Still check for national animosities and host-government reactions. (Study guide mini-case)");
// Ch 6
IM(6, 3, "A subsidiary's profit looks poor because transfer pricing moved its profit to another unit. Which constraint is this?", ["Whole vs. part", "Separation by time and distance", "Market maturity", "Volatility"], "The unit serves the global strategy, so local results can look poor on purpose. (Study guide, Ch 6)");
IM(6, 2, "Given the five MNE constraints, what does the study guide recommend for appraising subsidiary managers?", ["Use contextual goals and several measures, not a single profit target", "Use profit only, since it is the most comparable measure across units", "Use soft goals only, since hard numbers are distorted abroad", "Use the same targets as the most mature subsidiary in the MNE"], "(Study guide, Ch 6)");
IM(6, 2, "Which variable affecting expatriate performance does HR control LEAST?", ["The host environment", "The compensation package", "The task", "Headquarters' support"], "HR can still influence it through selection, CCT, contextual goals, and local mentors. (Study guide, Ch 6)");
IM(6, 3, "How should a DEVELOPMENTAL assignment be appraised?", ["On learning goals, competencies gained, and mentor feedback, plus some output", "On project delivery, whether the system works, and skill transfer to HCNs", "On market entry results, alliances, and stakeholder relations abroad", "On the adoption of processes and practices in both directions"], "Technical: project delivery. Strategic: strategic results and leadership. Functional: adoption of practices both ways. (Study guide, Ch 6)");
IM(6, 3, "How should a TECHNICAL assignment be appraised?", ["On project delivery, whether the system works, and skill transfer to HCNs", "On learning goals, competencies gained, and mentor feedback", "On alliances, stakeholder relations, and the strategic results for the MNE", "On two-way adoption of practices between HQ and the subsidiary"], "(Study guide, Ch 6)");
IM(6, 3, "Using role theory, why is a TCN manager at more risk than a PCN manager?", ["Two cultural boundaries create more role ambiguity and role conflict", "TCNs get no role expectations, so their goals are always unclear", "TCNs share HQ's culture, so host stakeholders reject them more often", "PCNs face two cultural boundaries, while TCNs face only one"], "Fix: clear written goals, regular HQ contact, raters who know all three contexts. (Study guide, Ch 6)");
IM(6, 3, "Why should an expatriate's appraisal combine hard, soft, AND contextual goals?", ["Hard goals alone punish people for the environment; soft are subjective; contextual makes numbers fair", "Hard goals are not allowed abroad, so soft and contextual goals must replace them entirely for expatriates", "Soft goals are always objective, so they should balance out the hard numbers", "Contextual goals replace all other goals once the environment becomes volatile"], "(Study guide, Ch 6)");
IM(6, 3, "What is a weakness of the HOME-country (HQ) manager as an expatriate's rater?", ["Remote and relies on hard numbers: 'out of sight, out of mind'", "Sees too much daily behavior and too little of the results", "Knows the local context so well that HQ goals are ignored", "Uses a local cultural lens that differs from HQ's view"], "Host raters know the context but can be culturally biased. Recommendation: multiple raters, weighted by who knows the context. (Study guide, Ch 6)");
IM(6, 3, "A host manager in a high-power-distance culture rates an expatriate's participative style as weak. What does this show?", ["Cultural bias in host-country raters", "Whole vs. part", "A technical assignment", "Contextual goals working as intended"], "(Study guide, Ch 6)");
IM(6, 2, "What does a STANDARDIZED appraisal form gain and lose compared with a customized one?", ["Gains comparability across units; loses local fit", "Gains local fit; loses comparability across units", "Gains cultural fit and also removes rater bias", "Gains nothing, since all units customize it anyway"], "Also consider frequency and feedback that fits the culture (direct vs. indirect, saving face). (Study guide, Ch 6)");
IM(6, 3, "Mini-case: Maria, a GM in Argentina, missed profit by 15% after a peso devaluation, but built government ties and trained an HCN successor. HQ rated her on profit alone. Which constraints did HQ ignore?", ["Volatility and non-comparable data (maybe whole vs. part)", "Separation by time and distance only (HQ is far away)", "Variable levels of market maturity only", "None; the profit-only appraisal was fair"], "The appraisal used only hard goals and a remote rater. (Study guide mini-case)");
IM(6, 3, "In Maria's case, which redesign best fits the chapter?", ["Measure profit at budgeted rates, add contextual and soft goals, and use host + HQ raters", "Keep profit as the only measure, but raise the target to reflect the devaluation", "Drop all hard goals, and rate Maria only on her relationships with the government", "Let Maria rate herself, and use HQ's rating only if the two scores disagree"], "Soft goals: government relations and HCN successor development. (Study guide mini-case)");
// Ch 7
IM(7, 2, "Using Mendenhall & Oddou, which training fits a 3-week audit in Canada (from the U.S.)?", ["Information-giving (short stay, similar culture)", "Immersion (long stay, novel culture)", "Affective (2–12 month job, some interaction)", "A preliminary visit with no other training"], "(Study guide, Ch 7)");
IM(7, 2, "Using Mendenhall & Oddou, which training fits a 2-year GM post in Saudi Arabia?", ["Immersion, including the family (long stay, high interaction, novel culture)", "Information-giving, with area briefings and survival-level language", "Affective, with role-plays and case studies over about a week", "A preliminary visit only, since the expatriate will learn on the job"], "(Study guide, Ch 7)");
IM(7, 2, "Why are preliminary visits valuable?", ["A realistic job preview: the family can decide and start adjusting, and bad fits drop out early", "They replace language training, since the family learns the language during the visit", "They act as a first performance appraisal before the assignment begins", "They guarantee a promotion on return, which motivates the expatriate to accept"], "(Study guide, Ch 7)");
IM(7, 2, "Why is host-language training useful even when English is the corporate language?", ["It improves interaction adjustment, informal information, and respect from HCNs", "It is required by most host countries before a work permit can be issued", "It replaces cultural awareness training, so the program can be shorter", "It matters only for flexpatriates, who meet many local customers"], "It also lowers dependence on interpreters (link to the language-node role). (Study guide, Ch 7)");
IM(7, 2, "Why are security briefings increasingly important?", ["The firm's duty of care in high-risk locations", "Security briefings now replace the need for careful selection", "They improve hard goals", "They are only needed for flexpatriates"], "(Study guide, Ch 7)");
IM(7, 3, "What did Morris & Robie's meta-analysis find about cross-cultural training?", ["A positive but modest effect on adjustment and performance", "No measurable effect on adjustment or performance", "A very large effect that guarantees assignment success", "A negative effect, because training raises anxiety"], "CCT helps but is not a cure; match rigor to the assignment. (Study guide, Ch 7)");
IM(7, 2, "What is the weakness of the Brookfield survey evidence on CCT?", ["It is self-evaluated, so it is open to bias", "It is a meta-analysis of older studies, so it is out of date", "It measured language training only", "It studied only domestic employees"], "(Study guide, Ch 7)");
IM(7, 2, "When should repatriation planning start?", ["Before departure", "On the day the expatriate returns", "Six months after return", "Only if the expatriate fails"], "Expatriation includes repatriation. (Study guide, Ch 7)");
IM(7, 3, "When repatriation is linked to outcomes, there is a feedback loop. What happens if repatriates are seen to quit or be sidelined?", ["Others refuse assignments, the pool shrinks, and the firm values international experience even less", "More employees volunteer, because they see quick promotions for those who leave the firm", "Knowledge sharing rises, because repatriates share more before they leave", "Nothing changes, because the outcomes do not feed back into the process"], "(Study guide, Ch 7)");
IM(7, 2, "(text) What is the main cause of repatriate turnover within 1–2 years?", ["A broken psychological contract: they expected promotion and use of their skills", "Too much pay on return compared with peers who stayed at home, which causes conflict", "Too many career-planning sessions that delay a decision on the next job", "Excess training, which makes them overqualified for their old jobs"], "(Study guide, Ch 7 — text)");
IM(7, 2, "Why do firms often FAIL to use repatriates' knowledge?", ["Lateral jobs, HQ sees local knowledge as irrelevant, no capture system", "Repatriates bring back mainly personal skills, not useful knowledge", "Host-country laws forbid sharing knowledge from the subsidiary", "Repatriates are promoted too fast to share what they learned"], "(Study guide, Ch 7)");
IM(7, 3, "Mini-case: after 3 years in Shanghai, Daniel returns to a lateral 'special projects' job, nobody asks about China, his partner can't find work, and he joins a competitor. Which repatriate adjustment factors are at work?", ["Career anxiety, work adjustment (weak job, devalued experience), status loss, partner career", "Culture shock out, host environment, and lack of headquarters' support while abroad", "Hard goals, soft goals, and contextual goals in his last appraisal in Shanghai", "Selection factors: technical ability, language, and cross-cultural suitability"], "Fig 7.6: low value on international experience → lost retention and knowledge sharing. (Study guide mini-case)");
IM(7, 3, "Which repatriation program element would MOST likely have kept Daniel?", ["A written agreement and sponsor, career planning, partner job help, and visible recognition", "A longer special-projects role so he has more time to readjust before taking on a new job", "Cutting his allowance faster so his pay matches peers who stayed at home", "No debriefing, so he can rest, and a review of his next role after a year"], "(Study guide mini-case)");
// Essay angles
IM(5, 3, "Essay angle: a firm says 'replace long-term expatriates with HCNs, short-term assignees, and virtual teams.' What is the strongest counter-argument?", ["Expatriates give control, socialization, networks, and knowledge transfer that are hard to do virtually", "HCNs always cost more than expatriates, so the plan would raise the firm's total costs over time", "Virtual teams have no performance management issues, so the plan would work well", "Polycentric staffing has no risks, so the firm should go further and drop HQ control"], "Best position: a portfolio of global work, matched to the assignment's purpose and type. (Study guide essay)");
IM(6, 3, "Essay angle: how does an ETHNOCENTRIC firm typically appraise its managers abroad?", ["HQ-driven, hard goals, standardized forms, one cultural boundary", "Multiple raters, contextual goals, two-boundary TCN issues", "Host-driven, soft goals only, customized forms in each unit", "Peer ratings from HCNs only, with no HQ involvement"], "Geocentric firms use multiple raters, contextual goals, and face TCN two-boundary issues. (Study guide essay)");
IM(7, 3, "Essay angle: why is repatriation unclear for TCNs?", ["'Home' can be the parent country or the TCN's own country", "TCNs always return to headquarters after each posting", "TCNs are treated as inpatriates once the assignment ends", "TCNs keep the same job in the host country after return"], "Plan the next move as career management. (Study guide essay)");


/* ===== Aligned to the official MGMT 660 Exam 2 Review (Ch 4–7 topic list) ===== */
// Ch 4 — types of assignments, purposes & roles, expatriate failure
IM(4, 1, "Which of these is NOT one of the eight types of global workers (types of assignment for expatriates) in Chapter 4?", ["Inpatriate consultants", "Short-term assignees", "International business travelers", "Global domestics"], "Ch 4 slide 3: corporate expatriates, short-term assignees, flexpatriates, self-initiated expatriates, international business travelers, international commuters, global virtual team members, global domestics.");
IM(4, 2, "A sales director makes frequent short business trips to customers in several countries but never takes an assignment. Which type of global worker is this?", ["International business traveler", "Corporate (long-term) expatriate", "Short-term assignee (3–12 months)", "Global domestic (works from home)"], "Ch 4 slide 3.");
IM(4, 2, "An engineer is sent to Poland for 8 months to fix a production problem; his family stays home. Which assignment type fits?", ["Short-term assignee", "Corporate expatriate", "Flexpatriate", "Global domestic"], "Table 4.2: short-term = 3–12 months, usually without family.");
IM(4, 2, "Which assignment purpose is MOST about the MNE as a whole, rather than the job or the person?", ["Organization development", "Position filling", "Management development", "Language training"], "Position filling = the job; management development = the person; organization development = the MNE (control, socialization, coordination).");
IM(4, 2, "An expatriate builds personal ties between people at HQ and the subsidiary so information and help flow across units. Which role is this?", ["Network builder", "Agent of direct control", "Language node", "Boundary spanner"], "Figure 4.1.");
IM(4, 2, "An expatriate teaches HCNs a new quality system that headquarters developed. Which expatriate role is this?", ["Transfer of competence and knowledge", "Language node between HQ and unit", "Network builder across the MNE", "Agent of direct control for HQ"], "Figure 4.1; also Ch 7 slide 3 (expatriates are trainers).");
IM(4, 2, "Which is a DIRECT cost of expatriate failure?", ["Relocation costs, salary paid, and the cost of sending a replacement", "Lost relationships with local customers and government officials", "Damage to the MNE's reputation in the host-country market", "Lower morale and productivity among host-country employees"], "Indirect costs: relationships, market share, reputation, morale.");
IT(4, 2, "Chapter 4 says the reasons for expatriate failure today are similar to those found in earlier studies.", true, "Ch 4 slide 11, though assignees' experiences have likely changed.");
IT(4, 2, "Chapter 4 says expatriate SUCCESS should also be defined more broadly, with subjective indicators such as career or life satisfaction.", true, "Ch 4 slide 11: 'This is also true for expatriate success.'");
// Ch 5 — staffing attitudes (benefits & drawbacks), determinants, selection, adjustment
IM(5, 2, "Which is a BENEFIT of an ethnocentric staffing approach?", ["Strong HQ control and coordination, and easy transfer of core skills", "No language barriers with local staff, and lower hiring costs", "A truly international executive team chosen on ability alone", "Better HCN morale, since they see future career potential"], "Drawbacks: limited HCN promotion, slow local adaptation, HCN resentment, and pay gaps between PCNs and HCNs. (Table 5.1)");
IM(5, 2, "Which is a BENEFIT of a polycentric staffing approach?", ["No language barriers and lower costs, since HCNs know the local market", "Strongest HQ control and coordination across all of the subsidiaries", "PCNs gain the most international experience in the MNE", "Managers move freely across the whole MNE regardless of origin"], "Drawback: a gap between HQ and subsidiaries — a federation of national units. (Table 5.1, HCNs)");
IM(5, 2, "Which is a DRAWBACK of a geocentric staffing approach?", ["It is costly, needs work permits and immigration help, and pay gets complex", "It limits the promotion chances of HCNs in their own subsidiary over time", "It can create a federation of national rather than global units", "It favors nationality over ability for key positions"], "Benefit: the best person for each job and a truly international executive team.");
IM(5, 2, "Which is a BENEFIT of a regiocentric staffing approach?", ["More interaction among managers moved within the region, and better regional fit", "Managers move freely between all regions and global HQ, regardless of origin", "The lowest transfer costs of any approach, since no one moves", "The strongest HQ control, since PCNs hold every key job"], "Drawback: regional silos ('regional federalism'); staff rarely reach global HQ.");
IM(5, 3, "A firm says 'nationality does not matter — we pick the best person, and anyone can run any unit.' Which drawback must its HR team plan for?", ["Immigration rules and complex, costly pay for a mobile workforce", "HCN resentment of a glass ceiling held by PCNs in key jobs", "A federation of national units with little HQ contact", "Regional silos where staff rarely reach global HQ"], "That is a geocentric attitude.");
IM(5, 2, "Which is NOT a 'company specificity' among the determinants of staffing choices?", ["Staff availability in the host country", "MNE structure and strategy", "International experience of the MNE", "Organizational culture of the MNE"], "Staff availability is a context specificity.");
IM(5, 2, "A firm opens a greenfield plant rather than acquiring one. Which group of staffing determinants does the establishment method belong to, and which way does a greenfield site usually push?", ["Local unit specificities, pushing toward PCNs (no existing local managers)", "Context specificities, pushing toward HCNs (local labor law and staff supply)", "IHRM practices, pushing toward TCNs (lower pay demands)", "Company specificities, with no effect on the staffing choice"], "An acquisition, by contrast, often has capable HCN managers already.");
IM(5, 2, "A host country has strict labor laws and visa limits on foreign managers. Which group of staffing determinants is this, and which way does it push?", ["Context specificities (institutional context), toward HCNs", "Company specificities (governance), toward PCNs abroad", "Local unit specificities (control), toward TCNs", "IHRM practices (selection), toward PCNs"], "Figure 5.1.");
IM(5, 3, "A strategically critical R&D subsidiary needs tight control and decisions are made at HQ. Which staffing determinants point toward PCNs?", ["Strategic role and importance, need for control, and locus of decision", "Cultural context, institutional context, and staff availability", "MNE structure and strategy, governance, and international experience", "Selection, training and development, and compensation practices"], "Figure 5.1.");
IM(5, 2, "Which determinant of staffing choice is an IHRM PRACTICE?", ["Compensation", "Type of industry", "Corporate governance", "Establishment method"], "IHRM practices: selection, training and development, compensation, career management.");
IM(5, 2, "In expatriate selection, what does the situational factor 'MNE requirements' refer to?", ["The firm's situation: mode of operation, assignment length, and knowledge to transfer", "The candidate's technical skills, managerial skills, and past job performance", "The partner's career, the children's schooling, and family adjustment", "The host country's culture, laws, and acceptance of foreign managers"], "MNE requirements is one of the three situational factors with country/cultural requirements and language.");
IM(5, 2, "A candidate is technically excellent but rigid, impatient, and judgmental about other cultures. Which selection factor is weak?", ["Cross-cultural suitability", "Technical ability", "MNE requirements", "Country/cultural requirements"], "Figure 5.2: an individual factor.");
IM(5, 2, "In the adjustment framework, a spouse who is unhappy in the host country is which kind of antecedent?", ["Non-work", "Job", "Organizational", "Individual"], "Figure 5.3/5.4 antecedents: individual, job, organizational, non-work.");
IM(5, 2, "Clear role expectations and support from the company during the assignment are which kinds of adjustment antecedents?", ["Job and organizational", "Individual and non-work", "Modes and outcomes", "Psychological and socio-cultural"], "Figure 5.3/5.4.");
IM(5, 2, "In the adjustment framework, what are 'modes' of adjustment?", ["Strategies of adjustment, such as coping", "The outcomes of adjustment (e.g., work)", "The antecedents of adjustment (e.g., job)", "The phases of the U-curve of adjustment"], "Antecedents → modes (strategies, e.g., coping) → outcomes.");
IM(5, 2, "An expatriate gets comfortable with daily life — food, housing, transport, and shopping. Which adjustment outcome is this?", ["General adjustment", "Interaction adjustment", "Work adjustment", "Repatriation adjustment"], "Interaction = with host nationals; work = the job.");
IM(5, 2, "An expatriate learns to socialize and communicate easily with host nationals. Which adjustment outcome is this?", ["Interaction adjustment", "General adjustment (daily life)", "Work adjustment", "Job antecedent"], "Figure 5.3/5.4.");
IT(5, 2, "Among the determinants of staffing choices, staff availability is a context specificity.", true, "Context: cultural and institutional context, staff availability, type of industry.");
IT(5, 2, "In expatriate selection, language is an individual factor.", false, "Language is a situational factor, with country/cultural requirements and MNE requirements.");
IT(5, 2, "The adjustment framework treats coping as an outcome of adjustment.", false, "Coping is a mode (strategy) of adjustment.");
// Ch 6 — constraints, variables, assignment types & PM, criteria, appraisal questions
IM(6, 2, "Of the five variables affecting expatriate performance, which is the MOST direct (the innermost layer)?", ["The compensation package", "Cultural adjustment of self and family", "Host environment", "Headquarters' support"], "From inner to outer: compensation package, task, headquarters' support, host environment, cultural adjustment (self and family).");
IM(6, 2, "An expatriate's pay package does not reward the hard parts of the job, so she focuses on easy tasks. Which variable affecting performance is this?", ["The compensation package", "The task (assignment and role)", "Host environment", "Headquarters' support"], "Ch 6 slide 5.");
IM(6, 2, "An expatriate's assignment goals and role are unclear and keep changing. Which variable affecting performance is this?", ["The task (assignment task variables and role)", "The host environment (the subsidiary itself)", "The compensation package and allowances", "Cultural adjustment of self and family"], "Ch 6 slide 5: 'the task — the assignment task variables and the expatriate's role.'");
IM(6, 2, "HQ forgets about an expatriate, answers her emails late, and gives no help with problems. Which variable affecting performance is this?", ["Headquarters' support", "The task", "Host environment", "Compensation package"], "Ch 6 slide 5.");
IM(6, 2, "A joint-venture partner and local regulations make an expatriate's plant hard to run. Which variable affecting performance is this?", ["Host environment (the subsidiary or facility)", "Headquarters' support for the assignee abroad", "The compensation package and allowances", "The task (assignment variables and role)"], "Ch 6 slide 5: 'the environment in which performance occurs.'");
IM(6, 3, "Which pairing of assignment type and appraisal focus is BEST?", ["Functional: two-way adoption of practices, with input from local raters", "Technical: mainly the assignee's personal learning and growth abroad", "Developmental: hard profit targets for the subsidiary only", "Strategic: only whether a new system was installed on time"], "Technical: delivery and skill transfer. Developmental: learning goals. Strategic: strategic results and leadership.");
IM(6, 2, "How often should international appraisals happen?", ["The MNE must decide it, e.g., annual reviews plus check-ins fitted to the assignment", "Once, at the end of the assignment, so the full result can be judged by HQ", "Every quarter, using the same calendar as domestic staff with no changes", "Only when HQ managers visit the subsidiary in person"], "Ch 6 slide 12 lists frequency as a key question.");
IM(6, 2, "Which question about appraisal deals with direct vs. indirect feedback and saving face?", ["How to communicate feedback", "Who conducts the appraisal", "Standardized or customized", "Frequency"], "Ch 6 slide 12; the related issue is cultural applicability.");
IM(6, 2, "A U.S. MNE uses a self-appraisal form in a culture where praising yourself is seen as rude. Which appraisal question does this raise?", ["Cultural applicability", "Frequency", "Who conducts the appraisal", "Whole vs. part"], "Ch 6 slide 12.");
IT(6, 2, "'Variable levels of maturity across markets' means a new subsidiary needs relevant comparative data before it is judged against mature units.", true, "Ch 6 slide 3.");
IT(6, 2, "Soft goals, such as leadership style, are easier to measure objectively than hard goals.", false, "Hard goals are quantifiable; soft goals are relationship- or trait-based.");
// Ch 7 — outcomes, T&D process, pre-departure, M&O, repatriation
IM(7, 2, "The international training and development process begins with which step?", ["Recruitment and selection", "Pre-departure training", "International assignments", "International team"], "Recruitment and selection → training (incl. pre-departure training) → international assignments ↔ development → international team.");
IM(7, 2, "In the international training and development process, what is the link between international assignments and development?", ["A two-way link: assignments develop people, and development shapes later assignments", "A one-way link: development must be finished before any assignment can begin", "A one-way link: assignments lead to development, but development has no effect back", "No direct link: development comes only from formal training programs"], "Figure 7.1 shows a double arrow between them.");
IM(7, 3, "In the international training and development process, which step is an optional END result?", ["International team", "Recruitment and selection", "Pre-departure training", "Development"], "Development can lead to an international team; selection also feeds assignments and teams directly (dashed lines).");
IM(7, 2, "Why does the international training and development process start with recruitment and selection instead of training?", ["Training builds on the people selected, so good selection makes training and the assignment work", "Selection is the cheapest step, so it is done first to reduce the total cost of the program", "Training is optional, so the process starts with the only required step", "Development must happen before hiring, so selection only confirms past development"], "Figure 7.1.");
IM(7, 2, "Which pre-departure training component covers the host culture's values and norms, so the expatriate can avoid culture shock?", ["Cultural awareness programs", "Security briefings", "Practical day-to-day assistance", "Preliminary visits"], "Ch 7 slide 5.");
IM(7, 3, "An expatriate needs only to get by in shops and taxis for a 3-week stay. Which level of language training matches Mendenhall–Oddou?", ["'Survival-level' language training (information-giving)", "Extensive language training (immersion approach)", "Moderate language training (affective approach)", "Full fluency training before any departure"], "Ch 7 slides 8–10.");
IM(7, 2, "Under the M&O model, a 6-month job with some interaction with locals calls for which approach?", ["Affective (moderate rigor, about 1–4 weeks)", "Information-giving (low rigor, under a week)", "Immersion (high rigor, 2+ months)", "Preliminary visit only (no formal training)"], "Ch 7 slide 9: 2–12 month job, some interaction.");
IM(7, 2, "Which method is part of the IMMERSION approach?", ["Intercultural web-based workshops and field experiences", "Lectures, movies, books, and area briefings", "Culture assimilator training and critical incidents", "Interpreters and survival-level language training"], "Ch 7 slide 10.");
IM(7, 2, "Which is an outcome of international assignments for the INDIVIDUAL?", ["Experience and career advancement", "A cadre of international operators", "Direct control and socialization", "Accumulated organizational knowledge"], "The others are MNE outcomes. Both gain a global mindset.");
IM(7, 2, "Why do direct control and socialization from international assignments help the MNE?", ["They help with knowledge transfer and competence transfer", "They let the MNE cut its training and development budget", "They let the MNE replace host-country nationals with PCNs", "They remove the need to plan for repatriation later"], "Ch 7 slide 2.");
IM(7, 2, "Which is one of the 'strategies for smooth re-entry'?", ["Extended home visits to keep up with social, family, and organizational changes", "Limiting contact during the assignment so the expatriate can focus on the host unit", "Waiting until the expatriate is back to discuss the next job and career path", "Cutting the allowance right away so pay matches peers who stayed at home"], "Ch 7 slide 21.");
IM(7, 2, "Which smooth re-entry strategy directly fights 'devaluing experience'?", ["Visible, concrete expressions of the repatriate's value", "Personalized financial and tax advice after the return", "Extended home visits during the assignment", "Pre-departure briefings on what to expect"], "Ch 7 slide 21 matched to Figure 7.5.");
IM(7, 2, "Which smooth re-entry strategy best addresses the loss of the overseas allowance?", ["Personalized financial and tax advice", "Mentoring that continues after return", "Reorientation on organizational changes", "Multiple career planning sessions"], "Ch 7 slide 21 matched to Table 7.3.");
IM(7, 2, "Which smooth re-entry strategy best addresses 'no post-assignment guarantee'?", ["Written repatriate agreements on return assignments", "Extended home visits during the assignment", "Personalized reorientation for social readjustment", "Stress management and communication training"], "Ch 7 slide 21 matched to Figure 7.5 (career anxiety).");
IM(7, 3, "Which smooth re-entry strategy best helps a returning family that feels out of touch with friends at home?", ["Personalized reorientation for social readjustment", "Written repatriate agreements on the return job", "Personalized financial and tax advice", "Multiple career planning sessions"], "Ch 7 slide 21 matched to the social factors in Figure 7.5.");
IT(7, 2, "'Providing an adjustment period upon return' is one of the strategies for smooth re-entry.", true, "Ch 7 slide 21.");
IT(7, 2, "Family adjustment is a job-related factor in repatriate adjustment.", false, "It is a social factor, with social networks and the effect on the partner's career.");
IT(7, 2, "In the international training and development process, pre-departure training comes after recruitment and selection and before international assignments.", true, "Figure 7.1.");

/* ===== More review-aligned questions: easy recall + slide content not yet covered ===== */
// easy recall (d1)
IM(4, 1, "What are the three purposes of international assignments?", ["Position filling, management development, organization development", "Position filling, cost control, and market entry abroad", "Management development, control, repatriation", "Organization development, training, selection"], "Ch 4: Edström and Galbraith.");
IM(4, 1, "How long is a corporate (long-term) expatriate assignment?", ["12 months or more", "3–12 months", "Usually 1–3 months", "Less than 2 weeks"], "Short-term: 3–12 months. Flexpatriates: usually 1–3 months.");
IM(4, 1, "A global domestic does international work how?", ["From home, with little or no travel", "On frequent short trips abroad", "By moving abroad for a year", "By commuting across a border"], "Ch 4: other forms of global workers.");
IT(4, 1, "Expatriate failure was traditionally defined as premature return.", true, "Ch 4 slide 11.");
IM(5, 1, "What is a PCN?", ["A parent-country national (from the HQ country)", "A person from the host country of the subsidiary", "A person from neither the parent nor host country", "A host-country employee moved to headquarters"], "HCN = host-country national; TCN = third-country national.");
IM(5, 1, "A German manager runs the Brazilian subsidiary of a U.S. MNE. What is she?", ["A third-country national (TCN)", "A parent-country national (PCN)", "A host-country national (HCN)", "A global domestic employee"], "She is from neither the parent (U.S.) nor the host (Brazil) country.");
IM(5, 1, "Which staffing attitude favors PCNs for key positions?", ["Ethnocentric", "Polycentric", "Geocentric", "Regiocentric"], "Ch 5 slide 2.");
IM(5, 1, "How many factors are in the expatriate selection model?", ["Six (three individual, three situational)", "Four (all individual)", "Five (two individual, three situational)", "Three (all situational)"], "Individual: technical ability, cross-cultural suitability, family requirements. Situation: country/cultural requirements, language, MNE requirements.");
IM(6, 1, "Which is one of the five MNE performance management constraints?", ["Non-comparable data", "Dual-career couples", "Culture novelty", "Preliminary visits"], "Whole vs. part, non-comparable data, volatility, separation by time and distance, variable market maturity.");
IM(6, 1, "Which are the four types of international assignments in Chapter 6?", ["Technical, developmental, strategic, functional", "Short-term, long-term, commuter, virtual", "Hard, soft, contextual, strategic", "Ethnocentric, polycentric, geocentric, regiocentric"], "Ch 6 slide 7.");
IM(7, 1, "How many essential components of pre-departure training are on the slide?", ["Five", "Three", "Four", "Seven"], "Cultural awareness programs, preliminary visits, language training, practical assistance, security briefings.");
IM(7, 1, "Put the three CCT approaches in order from LEAST to MOST rigorous.", ["Information-giving → affective → immersion", "Affective → information-giving → immersion", "Immersion → affective → information-giving", "Information-giving → immersion → affective"], "Mendenhall, Dunbar and Oddou.");
IM(7, 1, "The two groups of factors influencing repatriate adjustment are…", ["Job-related factors and social factors", "Individual factors and situational factors", "Hard factors and soft factors", "Host factors and home factors"], "Job-related: career anxiety, work adjustment, new role demands, status and pay. Social: family, networks, partner's career.");
IT(7, 1, "Home leave is a repatriation practice DURING the assignment.", true, "During: home leave, work-related information exchanges, communication with the sponsor, pre-return orientation.");
// assignment-length table rows not yet asked
IM(4, 2, "Which assigned expatriates usually NEED previous international experience?", ["Corporate (long-term) expatriates", "Short-term assignees", "Short-term assignees (3–12 months)", "None of the three types"], "Long-term: usually required. Short-term and flexpatriates: not necessarily required.");
IM(4, 2, "Flexpatriates are usually which kind of employee?", ["Field experts", "Mostly white-collar managers", "Talented prospects in training", "Host-country junior staff"], "Long-term: mostly white-collar managers or talented prospects. Short-term: managers, prospects, or field experts.");
IM(4, 2, "How many locations per year does a flexpatriate usually cover?", ["Potentially multiple countries", "One country only", "One or very few countries", "Only the home country"], "Long-term: one country. Short-term: one or very few.");
IM(4, 3, "What are the main organizational drivers for using FLEXPATRIATES?", ["Project-based work, problem-solving, skill/technical transfer", "Managerial control, management development, skill transfer", "Organization development and socialization over many years", "Filling a vacant top job at a subsidiary for a long period"], "Long-term: managerial control, skill transfer, management development.");
IM(4, 2, "How much do flexpatriates integrate at the host location?", ["Only limited", "Fully, like long-term expatriates", "More than long-term expatriates", "Not at all, by company policy"], "Long-term: yes (potentially). Short-term: yes, but probably less than long-term.");
// staffing table points not yet asked
IM(5, 2, "Which is an ADVANTAGE of using PCNs?", ["They may be the best people for the job because of special skills", "They remove language and other barriers with local employees", "They improve the morale of host-country employees", "They need no work permits in the host country"], "Other PCN advantages: control and coordination, international experience, compliance with MNE objectives.");
IM(5, 2, "Which is a DISADVANTAGE of using PCNs?", ["They may impose an inappropriate headquarters style", "They make HQ control and coordination harder", "They may not want to return to the home country", "They create a federation of national units"], "Also: limited HCN promotion, slow adaptation, and PCN–HCN pay gaps.");
IM(5, 2, "Which is an ADVANTAGE of TCNs over PCNs?", ["They may know the host-country environment better", "They guarantee compliance with MNE policies", "They remove all national animosities in transfers", "They never need a work permit or visa"], "TCNs may also cost less than PCNs.");
IM(5, 2, "Why can hiring HCNs improve morale in the subsidiary?", ["Local staff see future career potential", "Local staff gain foreign experience", "Pay for PCNs and HCNs becomes equal", "HQ style is applied more strictly"], "HCN advantage in the staffing table.");
// Ch 6 non-expatriate challenges
IM(6, 2, "Which is a performance management challenge for NON-standard international work (e.g., commuters, virtual teams)?", ["Ways to improve and what to reward are unclear", "Performance is easy to separate from domestic work", "Only HQ managers can see the work being done", "Cultural differences do not affect the criteria"], "Ch 6 slide 10.");
IM(6, 2, "How can non-standard international work affect HCN co-workers?", ["It can have an impact on them that appraisal must consider", "It has no effect, since HCNs never work with them", "It always improves their pay and promotion chances", "It replaces their need for performance appraisal"], "Ch 6 slide 10: 'impact of non-standard work on HCN co-workers.'");
IT(6, 2, "Appraisals of non-standard international work are complicated by the international context and the use of outside appraisers.", true, "Ch 6 slide 10.");
// Ch 7 training-tool roles, knowledge, repatriation program, figures
IM(7, 2, "Expatriates who show how systems and processes work and monitor HCN performance play which T&D role?", ["They ensure adoption", "They are trainers", "They are managers under development", "They act as language nodes"], "Ch 7 slide 3: trainers; ensure adoption; management under development.");
IM(7, 2, "Expatriates who gain a broader perspective through job rotation and become global operators fit which T&D role?", ["Management under development", "Trainers of HCNs", "Ensuring adoption of systems", "Agents of direct control"], "Ch 7 slide 3.");
IM(7, 2, "Communication, project management, and problem-solving gained abroad are which kind of repatriate skill?", ["Job-related management skills", "Market-specific knowledge", "Personal skills", "Network knowledge"], "Ch 7 slide 19.");
IM(7, 2, "Meeting diverse people during an assignment builds which kind of knowledge?", ["Network knowledge", "Market-specific knowledge", "General management capacity", "Personal skills"], "Ch 7 slide 19.");
IM(7, 2, "Which topic is part of a repatriation program?", ["School systems and children's education", "Selecting the next host country", "Hard and soft goals for the next year", "Host-country language training"], "Repatriation program topics also include physical relocation, workplace changes, stress management, networking, and new social contacts.");
IM(7, 2, "Changes in corporate culture, structure, or decentralization while you were away fall under which repatriation program topic?", ["Workplace changes", "Reverse culture shock", "Re-entry position", "Financial assistance"], "Repatriation program topics.");
IM(7, 2, "Which is a PRE-DEPARTURE repatriation practice?", ["Web and media contacts for context", "Systematic pre-return orientation", "Rituals to share the experience", "Work-related information exchanges"], "Pre-departure: sponsor, communication protocols, web/media contacts, pre-departure training and orientation.");
IM(7, 2, "Which is a DURING-ASSIGNMENT repatriation practice?", ["Systematic pre-return orientation", "Assigning a sponsor", "Organizational reconnection", "Establishing communication protocols"], "During: home leave, work-related information exchanges, communication with the sponsor, systematic pre-return orientation.");
IM(7, 3, "What is the end goal of repatriation activities and practices?", ["A new, balanced, integrated global perspective", "A return to a purely home-country focus", "A permanent host-country focus", "A shorter next assignment"], "The process moves from home focus to host focus (culture shock out) and back (culture shock back).");
IM(7, 3, "When repatriation is linked to outcomes, what shapes how the firm manages the repatriation process?", ["The value it places on international experience", "The host country's tax and labor rules", "The expatriate's selection scores", "The length of pre-departure training"], "Value placed on international experience → management of the repatriation process → outcomes (retention, commitment, knowledge sharing).");

