/* Topics outside the Exam 2 Review list stay in the bank but come up less often (see drawQ). */
const IHRM_OFF = /Table 4\.1|Table 5\.6|by status|low status|taxonomy|cognitive flexibility|horizontal comparison|dual.career|glass ceiling|Adler|female expat|women|of MNE performance management\?|critical issues|MNE control and performance|GPM|funneling|role conception|role theory|role sender|international teams|TREND|international teams are developed/i;
for (const q of IHRM_QS) q.core = !IHRM_OFF.test(q.q);

